    body: "高校中退とは、生徒が高等学校の課程を修了せずに退学することを指します。日本の高校進学率は98%を超える一方、経済的困窮、学業不振、不登校、人間関係のトラブル、進路のミスマッチなど複合的な要因によって、一定数の生徒が卒業前に学校を離れています。\n\n教育社会学では、高校中退が個人の一時的な選択にとどまらず、出身家庭の経済状況や親の学歴といった社会階層の要因と統計的に強く関連していることが明らかにされてきました。中退はその後の非正規雇用への従事や低所得といった不利を招きやすく、貧困の世代間連鎖を助長する要因の一つとしても位置づけられています。\n\nこのため近年は、中退の予防や中退後の学び直し支援（定時制・通信制課程、高卒認定試験、若者サポートステーションなど）が政策課題として重視されており、学校と福祉・労働分野との連携によるセーフティネットづくりが進められています。中退の背景を早期に把握し、教育相談やスクールソーシャルワーカーと連携した支援体制を整えることも、中退を防ぐ上で重要とされています。",
