    body: "地位達成モデルとは、個人が到達する社会的地位（主に職業的地位）が、出身家庭の地位（父親の職業や学歴など）や本人の教育達成といった諸要因を通じてどのように規定されるかを、パス解析などの統計的手法で分析する社会階層研究の枠組みです。アメリカの社会学者ピーター・ブラウとオーティス・ダンカンが1967年の著作『アメリカの職業構造』で確立し、以後の社会移動研究に大きな影響を与えました。\n\nこのモデルは、出身家庭の地位から本人の地位への直接的な影響（属性主義的経路）と、教育達成を経由する間接的な影響（業績主義的経路）とを区別して分析できる点に特徴があります。これにより、ある社会がどの程度「開かれた」社会か、すなわち出身に左右されず教育を通じて地位を達成できる社会かを、実証的に検討することが可能になりました。\n\n日本でも社会階層と社会移動全国調査（SSM調査）などを用いた地位達成研究が蓄積されており、教育が社会移動の主要な経路として機能していることや、その機能の変化が繰り返し検証されています。",
