    body: "社会移動とは、個人が社会階層や社会的地位の間を移動する現象を指し、同一世代内でのキャリアの変化を捉える「世代内移動」と、親の世代と子の世代の地位を比較する「世代間移動」に大別されます。移動の方向によって、地位が上がる「上昇移動」と下がる「下降移動」にも区分されます。\n\n教育社会学では、学校教育、とりわけ高等教育への進学が、出身家庭の階層にかかわらず個人が上昇移動を遂げるための主要な経路として位置づけられ、「教育を通じた社会移動」というテーマのもとで数多くの実証研究が蓄積されてきました。一方で、教育達成そのものが出身家庭の経済的・文化的資源に強く規定されているため、教育が階層の固定化を緩和する機能と、逆に階層を再生産してしまう機能とを併せ持つことが指摘されています。\n\n日本では、高度経済成長期には進学率の上昇に伴い比較的活発な上昇移動がみられましたが、近年は社会全体の流動性の低下が指摘され、教育を介した移動の機会がどう変化しているかが継続的に検証されています。",
