    body: "ジェンダーと教育とは、生物学的な性別（セックス）とは区別される社会的・文化的な性差（ジェンダー）が、学校教育を通じてどのように形成され、また再生産されるのかを分析する教育社会学の研究領域です。教科書の記述や教師の児童生徒への接し方、進路指導における理系・文系のコース選択の偏りなど、学校生活のさまざまな場面に性別による差異や期待が埋め込まれていることが指摘されてきました。\n\nこうした性別に基づく扱いの違いは、明文化されたカリキュラムには現れない「隠れたカリキュラム」の一形態として論じられることが多く、生徒自身の進路希望や自己認識の形成にも影響を与えるとされます。日本では大学進学率や理工系分野への進学における男女差が長年の研究テーマとなっており、国際的にもSTEM分野におけるジェンダーギャップの是正が政策課題とされています。\n\n近年は男女共学化や男女平等教育の推進に加え、性の多様性（LGBTQ等）への配慮を含めた、より広い意味でのジェンダー公正な教育のあり方が議論されるようになっています。",
