    body: "社会関係資本（ソーシャル・キャピタル）とは、人々の間の信頼、互酬性の規範、社会的ネットワークなど、人間関係そのものを一種の資源としてとらえる概念です。アメリカの社会学者ジェームズ・コールマンが教育研究の文脈でこの概念を用い、後にロバート・パットナムが政治学・地域研究の文脈で発展させたことで広く知られるようになりました。\n\nコールマンは、家庭内での親子の関わりの緊密さや、家庭と学校、地域社会との間の結びつきといった社会関係資本が、子どもの学業達成に対して、経済資本や人的資本とは独立した影響を持つことを実証的に示しました。地域や親同士のつながりが豊かな環境ほど、子どもの規範意識や学習意欲が育まれやすいとされます。\n\nこの概念は、家庭や地域のつながりの希薄化が子どもの育ちに与える影響を論じる際の理論的基盤としても用いられ、コミュニティ・スクールなど学校と地域の連携を重視する近年の教育政策の背景にある考え方の一つともなっています。都市化や単身世帯の増加により地域の結びつきが弱まるなかで、学校を核とした社会関係資本の再構築が課題として論じられています。",
