    body: "ペアレントクラシーとは、「親（parent）」と「支配（-cracy）」を組み合わせた造語で、子どもの教育達成が本人の能力や努力（メリット）よりも、保護者の経済力や教育に対する熱意・選択によって左右される傾向を指す概念です。イギリスの社会学者フィリップ・ブラウンが1990年の論文で、教育制度がメリトクラシーからペアレントクラシーへと移行しつつあると論じたことに由来します。\n\n学校選択制の広がりや、私立中学受験・学習塾の利用拡大などにより、保護者がどれだけ情報を集め、教育投資を行えるかが子どもの進学結果を左右する度合いが強まっているとされます。日本でも、私立中学受験の広がりを背景に、この概念を用いてこの現象を分析する研究が2000年代以降に蓄積されてきました。\n\nペアレントクラシーの視点は、公教育が本来目指す機会均等の理念と、現実に生じている家庭背景による教育格差との間の緊張関係を浮き彫りにするものとして、教育社会学における重要な分析枠組みとなっています。",
