    body: "学校効果研究とは、児童生徒の学力や社会性の発達が、出身家庭の経済的・文化的背景だけでなく、実際に通う学校の違いによってどの程度左右されるのかを、統計的な手法を用いて明らかにしようとする研究分野です。1966年に発表されたアメリカの「コールマン報告書」が、学校間の資源格差よりも家庭背景の影響の大きさを示したことが議論の出発点となり、その後の研究の展開を促しました。\n\nイギリスのマイケル・ラターらによる「フィフティーン・サウザンド・アワーズ」研究などを経て、教員間の協働性やリーダーシップ、学校としての一貫した指導方針、生徒に対する高い期待といった学校の組織的な特性が、家庭背景の影響を統制してもなお学力に一定の効果を持つことが明らかにされてきました。\n\n日本では2000年代以降、マルチレベル分析などの手法を用いた学校効果の実証研究が進められ、学力調査の結果を学校単位で分析し、効果的な学校運営のあり方を検討する取り組みにもつながっています。全国学力・学習状況調査などのデータを活用し、家庭背景を統制したうえで学校の取り組みの効果を評価する試みも広がりつつあります。",
