    body: "トラッキングとは、学力や進路希望に応じて生徒が異なるコースや学校の種類へと振り分けられ、その振り分け（トラック）によって、その後に選択できる進路の範囲や可能性があらかじめ限定されていく仕組みを指す概念です。高等学校の普通科・専門学科・偏差値による学校間の序列、あるいは大学における学部・学科の選択などが、日本におけるトラッキングの具体例として研究されてきました。\n\n教育社会学の研究では、いったんあるトラックに位置づけられると、そこから別のトラックへ移ることが制度的にも心理的にも難しくなり、結果として出身階層による教育格差が学校段階を通じて維持・拡大されやすいことが指摘されています。トラッキングは生徒本人の教育に対する期待や進路意識そのものを方向づける働きも持つとされます。\n\nこうした問題意識から、アメリカなどでは能力別学級編成を緩和する「脱トラッキング」の政策的な取り組みも行われており、選抜と機会均等のバランスをどう図るかが継続的な論点となっています。",
