    body: "貧困の世代間連鎖とは、親世代が経済的に困窮している状況が、子ども世代にもそのまま引き継がれ、貧困が世代を超えて再生産されていく現象を指します。家庭の経済的困難は、学習塾や習い事などの教育投資の不足、家庭内での学習環境の乏しさ、進学に対する期待の低さなどを通じて子どもの学力や進学機会に影響し、結果として子どもも低学歴・不安定就労・低所得に陥りやすくなるという因果の連鎖が想定されています。\n\n日本では、ひとり親世帯における相対的貧困率の高さが国際的にも指摘されており、子どもの貧困対策の推進に関する法律（2013年制定）の制定を契機に、貧困の連鎖を断ち切るための学習支援や居場所づくりなどの取り組みが各地で進められてきました。\n\n教育社会学では、この連鎖のメカニズムを、文化資本や社会関係資本の乏しさ、学校外教育機会の格差、自己効力感の低下など複合的な要因から説明する研究が蓄積されており、教育政策単独ではなく福祉政策と連携した対応の必要性が論じられています。",
