    body: "青年期の友人集団に関する研究は、思春期の生徒たちが学校のなかで形成する仲間集団が、大人社会や学校の公式な価値観とは異なる独自の価値観・地位序列・行動規範を持つことに着目します。アメリカの社会学者ジェームズ・コールマンは1961年の著作『青年期の社会』で、高校生の間ではスポーツや容姿、異性関係での人気が、学業成績よりも高く評価される傾向があることを実証的に示し、こうした「生徒文化」が学業に対する生徒の努力を弱めうると論じました。\n\nこの研究は、学校という制度が単に知識を伝達する場であるだけでなく、生徒同士の相互作用を通じて独自の社会（生徒社会）を形成する場でもあることを示した点で、教育社会学に大きな影響を与えました。\n\n日本においても、部活動や友人グループを中心とした生徒文化が学習意欲や進路意識、いじめなどの問題行動とどのように関連するかについて、学校エスノグラフィーなどの手法を用いた研究が蓄積されています。近年注目される「スクールカースト」と呼ばれる生徒間の人気序列の研究も、こうした友人集団論の系譜に連なるものといえます。",
