    body: "ラベリング理論とは、ある行為が「逸脱」となるのは、その行為自体に固有の性質があるからではなく、周囲の人々や社会がその行為に「逸脱」というレッテル（ラベル）を貼ることによって初めて成立する、と考える社会学の理論です。1960年代にアメリカの社会学者ハワード・ベッカーらによって体系化され、犯罪社会学や逸脱行動論の代表的な視点の一つとなりました。\n\n学校教育の文脈では、教師が特定の生徒に「問題児」「できない子」といったラベルを貼ることで、その生徒自身が周囲の評価を内面化し、実際にラベルにふさわしい行動を取るようになってしまう「予言の自己成就」的なプロセスが生じうることが指摘されています。不登校や非行、特別支援の対象認定などをめぐる教師や学校の対応を分析する際に、この理論的視点が用いられます。\n\nラベリング理論は、問題行動を個人の資質のみに帰属させるのではなく、それを「問題」として名指し、対応する学校や社会の側の反応過程そのものを分析の対象とする点に特徴があり、生徒指導のあり方を批判的に検討する視点を提供しています。",
