    body: "抵抗理論とは、学校の権威や価値観に対する生徒の反抗や逸脱的な行動が、単なる問題行動としてではなく、既存の学校文化や支配的な価値観に対する主体的な「抵抗」として意味を持つとする考え方です。イギリスの社会学者ポール・ウィリスが1977年の著作『ハマータウンの野郎ども』で示した研究が代表的で、労働者階層出身の男子生徒集団（「野郎ども」）が学校の勉学中心の価値観を見下し、独自の反学校文化を形成する過程を詳細に描き出しました。\n\nウィリスの分析の重要な点は、生徒たちが学校文化への反抗を通じて自ら進んで肉体労働の世界を選び取っていくにもかかわらず、その主体的な選択が結果として労働者階級としての地位を再生産してしまうという逆説を明らかにしたことにあります。単なる文化的再生産論とは異なり、生徒側の能動性・主体性に着目した点が高く評価されています。\n\nこの理論は、非行や反学校的な生徒文化を、階層構造との関係のなかで捉え直す視点を提供し、その後の教育社会学における生徒文化研究に大きな影響を与えました。",
