    body: "言語コード論とは、イギリスの社会学者バジル・バーンスティンが提唱した理論で、人々が用いる言語の使い方には、状況に応じた文脈を細かく言葉で説明する「精密コード」と、共有された文脈に依存し省略の多い「限定コード」の二種類があり、これが社会階層によって異なった形で身につけられると論じるものです。バーンスティンによれば、中産階層の家庭では両方のコードを状況に応じて使い分けられるようになる一方、労働者階層の家庭では限定コードが中心となる傾向があるとされます。\n\n学校教育で用いられる言葉づかいや評価の基準は、精密コードに親和的であることが多いため、限定コードを主に用いる労働者階層出身の子どもは、学校の言語文化になじみにくく、学業達成の面で不利になりやすいと論じられました。\n\nこの理論は、学力格差の要因を家庭の言語環境という具体的な次元から説明した点で大きな影響力を持ちましたが、労働者階層の言語使用を一面的に「不利」と評価することへの批判もあり、日本でも実証的な検証が行われています。",
