    body: "人的資本論とは、教育や職業訓練、健康への支出を、機械や設備への投資と同じように、個人の知識・技能・生産性を高めるための「投資」としてとらえる経済学の理論です。アメリカの経済学者セオドア・シュルツやゲイリー・ベッカーらによって1960年代に体系化され、ベッカーは1992年にこの分野の功績によりノーベル経済学賞を受賞しました。\n\nこの理論では、個人が進学によって獲得する学歴や技能は「人的資本」として蓄積され、将来のより高い賃金という形でその投資の見返り（収益率）が得られると考えます。国家レベルでも、教育への投資が労働生産性の向上や経済成長を通じて社会全体に利益をもたらすとされ、教育政策や奨学金制度の経済的な正当化の根拠として広く用いられてきました。\n\n教育社会学の立場からは、人的資本論が学歴と所得の関係を個人の合理的な投資選択として説明する一方で、その投資能力自体が出身家庭の経済状況に左右される点を見落としがちであるとして、地位達成モデルや文化的再生産論との対比のなかで批判的に検討されています。",
