    body: "対応原理とは、アメリカの経済学者サミュエル・ボウルズとハーバート・ギンタスが1976年の著作『アメリカ資本主義と学校教育』で提示した理論で、学校における社会関係（教師と生徒の権力関係、規則への服従、成績による評価など）の構造が、資本主義社会における職場の労働関係の構造とそのまま「対応」しているとする考え方です。\n\nこの理論によれば、将来単純労働に従事することが見込まれる労働者階層出身の生徒には、規則への服従や時間厳守といった従順さを養う指導が行われやすく、逆に将来管理職などに就くことが見込まれる階層の生徒には、自主性や創造性を伸ばす指導が行われやすいとされます。こうして学校教育は、資本主義経済が必要とする労働力を、階層構造をそのまま反映した形で再生産する装置として機能すると論じられました。\n\n対応原理は、学校を通じた社会移動の機会という楽観的な見方に対し、教育制度そのものが既存の経済的不平等を維持・正当化する構造的な役割を担っているという、批判的な教育社会学の立場を代表する理論として位置づけられています。",
