    body: "エミール・デュルケームはフランスの社会学者で、教育社会学の創始者の一人とされています。彼は教育を個人の内面から自然に生まれるものではなく、社会が世代を超えて自らを再生産するために行う「組織的な社会化」として捉えました。教育を通じて子どもは所属する社会の道徳・知識・技能を内面化し、社会統合の担い手となっていくと考えました。\n\nデュルケームは主著『教育と社会学』などで、教育は時代や社会集団ごとに異なる姿をとる社会的事実であり、普遍的で不変の理想像は存在しないと論じました。教育の内容や方法は、その社会の分業の程度や集合的意識のあり方によって規定されるとし、社会構造と教育制度を結びつけて分析する視点を確立しました。\n\nこの社会化論は、その後の機能主義的な教育社会学の基礎となり、学校が個人を社会に適応させる機関として機能する仕組みを説明する理論的土台になりました。一方で、社会の再生産を強調するあまり個人の主体性や社会変革の契機を軽視しているという批判も後の新しい教育社会学から寄せられています。",
