    body: "教師の多忙化とは、授業以外の校務分掌・部活動指導・保護者対応・事務作業などが積み重なり、教員の労働時間や精神的負担が著しく増大している状態を指します。教育社会学では、教師役割が学習指導にとどまらず生活指導や福祉的機能にまで際限なく拡大していく構造的な要因として分析されており、日本の教員の労働時間の長さは国際調査でもたびたび指摘されています。\n\nバーンアウトは、こうした慢性的なストレス状態の結果として生じる情緒的消耗感・脱人格化・個人的達成感の低下を特徴とする症候群で、対人援助職に特有の現象として心理学と社会学の双方から研究されてきました。日本では公立学校教員の精神疾患による休職者数の増加を背景に、多忙感の主観的側面や学校組織文化との関連を検討する研究が進められています。\n\n近年は「働き方改革」の一環として業務の外部化やICT活用による負担軽減策が議論されていますが、教育社会学の観点からは、教師役割そのものの範囲をどう社会的に再定義するかという構造的な問いが引き続き重要な論点となっています。",
