    body: "イヴァン・イリイチはオーストリア出身の思想家で、著書『脱学校の社会』(Deschooling Society)において、近代の学校制度が「学習」と「学校で教えられること」を混同させ、教育を国家や専門家が独占的に管理する制度に変質させたと批判しました。彼はこれを学校化(スクーリング)と呼び、人々が本来持っていた自律的な学びの力を奪う「制度への依存」を生み出していると論じました。\n\nイリイチは学校だけでなく医療や交通といった近代の諸制度全般が、当初の目的を離れて自己増殖し人々を受動的な消費者に変えてしまう「対抗生産性」の問題を指摘し、その解決策として、誰もが必要な時に学習資源にアクセスできる「学習のためのウェブ」という脱制度的な仕組みを構想しました。\n\nこの急進的な批判は実現可能性の乏しさなどから賛否を呼びましたが、学校教育を自明の前提とせず相対化する視点を提供した点で、その後のフリースクール運動やオルタナティブ教育、学校の脱制度化を論じる研究に大きな影響を与えました。",
