    body: "コールマン報告(正式名称『教育機会の均等』)は、社会学者ジェームズ・コールマンを中心とする研究チームが1966年にアメリカ合衆国政府の委託を受けて発表した、公民権法に基づく大規模教育調査の報告書です。全米数十万人規模の児童生徒を対象に、学校施設や教員の質といった学校側の要因と、生徒の学力達成との関係を統計的に分析しました。\n\n調査の結果、当時の予想に反して、学校の設備や予算、教員の資格といった学校側の資源の差は生徒間の学力格差をそれほど説明せず、生徒の家庭の社会経済的背景や、通う学校の他の生徒たちの家庭背景(仲間集団効果)の方が学力に強い影響を及ぼしていることが明らかになりました。この知見は「学校は無力である」という単純化された解釈も含めて大きな論争を呼びました。\n\nコールマン報告は、教育の機会均等を学校資源の平等な配分だけで実現しようとする政策の限界を示し、人種統合バス通学政策など、その後のアメリカの教育政策論争に大きな影響を与えました。教育社会学においては、学校効果研究や家庭背景と学力の関係を検討する研究の重要な出発点として位置づけられています。",
