    summary:
      "構造機能主義の社会学者タルコット・パーソンズが1959年の論文で示した理論で、学級を一つの社会システムととらえ、児童生徒の「社会化」と将来の社会的地位への「選抜(役割配分)」という二つの機能を同時に果たす場として分析した。",
    body: "タルコット・パーソンズは1959年の論文「学級-一つの社会体系」(The School Class as a Social System)において、初等・中等教育段階の学級を、家族と職業世界の中間に位置する独自の社会システムとして描き出した。学級は単なる知識伝達の場ではなく、成員である児童生徒に共通の価値と役割期待を内面化させる「社会化」の機能と、学業成績という業績本位の基準に基づいて生徒を序列づけ、将来の職業的地位へと配分していく「選抜」の機能を同時に担うとされる。\n\nこの理論はデュルケームの社会化論を継承しつつ、パーソンズ自身の構造機能主義の枠組みに位置づけられている点に特徴がある。学級では特殊主義的な家族関係とは異なり、共通の教師によって同一の基準で評価される普遍主義的・業績主義的な原理が働くとされ、これによって子どもは近代社会に適応するための価値志向を獲得していくと説明される。成績による評価は単なる学力の測定にとどまらず、児童生徒間に地位の分化を生み出し、それが後の学歴・職業達成の出発点になるとされた。\n\nこの議論は、学校が能力主義(メリトクラシー)的な選抜装置として機能するという見方の理論的基盤の一つとなった一方で、後にボウルズとギンタスの対応原理論や、ブルデューらの文化的再生産論からは、パーソンズの理論が学校選抜の公正さを過度に前提視し、階層による格差を等閑視していると批判された。それでも学級を社会システムとして分析する視点は、その後の教育社会学における学校組織研究の出発点の一つとして参照され続けている。",
    relatedSlugs: ["durkheim-kyoiku", "coleman-report", "meritocracy", "taiou-genri"],
