    body: "ウィラード・ウォーラーは1932年の著書『教授の社会学』(The Sociology of Teaching)において、教師と生徒の関係を社会学的に分析した最初期の体系的研究を行った。彼は教師・生徒の関係を「制度化された支配と従属(institutionalized dominance and subordination)」の関係と特徴づけ、それが公式の権威や制裁によって支えられているというよりも、教師個人の人格的な威信に大きく依存する、きわめて不安定で「かすかな均衡」の上に成り立つ関係であると論じた。\n\nウォーラーの視点の独自性は、学校を調和的な共同体としてではなく、教師と生徒という異なる欲求・目標を持つ集団同士の潜在的な対立の場として描いた点にある。教師は授業や規律を通じて生徒を統制しようとする一方、生徒集団は独自の仲間文化や規範を形成して教師の統制に抵抗し、両者の間には表面化しないまでも構造的な葛藤が常に存在するとされた。この葛藤の視点は、後の学校エスノグラフィーや教室相互作用の研究、さらには教師文化研究の先駆けとなった。\n\n本書はまた、教師という職業に伴う心理的緊張や、権威を維持するために生徒との間に感情的距離を置かざるを得ない「教師的パーソナリティ」の形成についても論じており、教職の社会学的研究の出発点として位置づけられている。機能主義が学校の統合的側面を強調したのに対し、ウォーラーの議論は学校内部の緊張関係に光を当てるものであり、後のコンフリクト理論的な教育社会学の系譜にもつながる先駆的業績と評価されている。",
    relatedSlugs: ["gakko-ethnography", "seito-shido", "hargreaves-kyoshi-bunka"],
    isCanonical: true,
    tags: ["教師生徒関係", "学校エスノグラフィー", "教職文化"],
