    body: "ランドル・コリンズは1979年の著書『資格社会』(The Credential Society)において、近代社会における教育年数と学歴要件の拡大を、コンフリクト理論(闘争社会学)の立場から批判的に分析した。コリンズの中心的主張は、学歴要求の上昇は職務遂行に必要な技術的スキルの向上によって説明されるという機能主義的な「技術機能主義」の見方を否定し、教育はむしろ特定の文化的作法や態度、社会的礼儀作法を体現していることを示す地位のシグナルとして機能していると論じた点にある。\n\nコリンズによれば、学歴を持つ集団は自らの職業的独占(occupational closure)を維持するために、参入資格として学歴要件を用いて他集団を排除する。これは特定の職業・地位集団(ウェーバーのいう身分集団)同士の文化的威信をめぐる闘争の帰結であり、学校教育の拡大そのものが技能水準の向上を必ずしも伴わないまま、学歴要求だけがエスカレートしていく「資格インフレ」を生み出すとされた。高校教育や大学教育の大衆化が進むほど、それらの学歴の相対的な価値は低下し、人々はより高い学歴を求めて競争を続けることになる。\n\nこの理論は、日本の「学歴社会」論や「学歴貴族」論とも通底する視点を提供するとともに、後のロナルド・ドーアの「学歴病」論とも呼応し、教育拡大と労働市場・社会的地位配分との関係を批判的に問い直す議論の礎となった。資格社会論は、教育を人的資本の形成としてのみ捉える経済学的な見方に対する社会学からの重要な対抗理論として位置づけられている。",
