    kana: "こ",
    categories: ["sociology"],
    summary:
      "アメリカの社会学者マーティン・トロウが1973年に提唱した理論で、高等教育の量的拡大を進学率に応じて「エリート型」「マス型」「ユニバーサル型」の3段階に区分し、それぞれの段階で高等教育の機能や性格が質的に変化するとした。",
    body: "マーティン・トロウは1973年の報告書「エリートからマスへの高等教育の移行における諸問題」の中で、各国の高等教育システムを該当年齢人口に占める進学率に応じて三つの発展段階に区分するモデルを提示した。進学率が15%未満の段階を「エリート型」、15%から50%の段階を「マス型」、50%を超える段階を「ユニバーサル型(universal access)」と呼び、単なる規模の拡大にとどまらず、各段階で高等教育の目的・機能・社会的意味そのものが質的に転換すると論じた。\n\nエリート段階の高等教育は、支配的地位を担う少数のエリート層の人格形成と精神の陶冶を目的とするのに対し、マス段階では技術者や専門職など、より広範な階層に必要な技能の伝達へと機能が移行する。さらにユニバーサル段階に至ると、高等教育は急速に変化する社会・技術環境に人口全体を適応させるための手段として位置づけられ、教育内容や大学の役割そのものが多様化・大衆化するとされた。\n\nこのモデルは各国の高等教育政策を比較分析する枠組みとして広く援用され、日本を含む多くの国の大学進学率の推移や大学改革の議論において参照されてきた。一方で、進学率という量的指標のみで質的な転換を説明することへの批判や、国ごとの制度的文脈の違いを十分に反映できないという指摘もあり、後継の研究では地域差やアクセスの多様化をより精緻に捉えるモデルへの発展が試みられている。",
    relatedSlugs: ["koudai-setsuzoku-kaikaku", "daigaku-jichi-no-rekishi", "daigakuin-juten-ka"],
