    body: "ピア・カルチャーとは、学校という制度の中で、児童生徒が同年代の仲間同士のやりとりを通じて自律的に形成していく規範・価値観・言葉づかい・遊びの様式などの総体を指す概念である。教師や学校が公式に伝える価値(学業達成、規律の遵守など)とは別に、生徒集団の内部には独自の地位序列や「かっこよさ」の基準、時には教師の権威に対する抵抗的な態度までもが存在し、これらは公式のカリキュラムに劣らず生徒の行動や意識形成に強い影響を及ぼすとされる。\n\nこうした仲間文化への社会学的関心は、ジェームズ・コールマンの『青年期社会』における高校生の地位システム研究や、ポール・ウィリスによる労働者階級の男子生徒の「対抗文化」研究などに代表される。ウィリスの研究では、生徒たちが学校の権威に反抗する仲間文化を形成する一方で、その反抗的な態度自体が皮肉にも彼らを労働者階級の職業へと導いてしまう過程が描かれ、仲間文化が階層の再生産と密接に結びついていることが示された。\n\n近年では、SNSなど新たなコミュニケーション手段の普及によって仲間文化の形成の場が教室外にも拡張しており、いじめやネットいじめ、仲間はずれといった負の側面から、互いの学びを支え合うピアサポートのような肯定的な機能まで、その影響は多面的に研究されている。教師にとっては、公式のカリキュラムだけでなく、こうした非公式な仲間文化の力学を理解することが、学級経営や生徒指導において重要な視点となる。",
