    summary:
      "イギリスの社会学者ロナルド・ドーアが1976年の著書『学歴病社会』で提示した概念で、後発国ほど就職選抜における学歴・資格への依存度が急速に高まり、教育が実質的な能力形成よりも資格取得競争そのものを目的化してしまう現象を指す。",
    body: "ロナルド・ドーアは、スリランカの若年失業問題を調査するILO(国際労働機関)の調査団に参加し、6週間にわたって各地の学校を訪問して校長や教育行政関係者と対話を重ねた経験をもとに、1976年の著書『学歴病社会』(The Diploma Disease: Education, Qualification and Development)を著した。ドーアはイギリス、日本、スリランカ、ケニアという発展段階の異なる四か国の教育史をたどりながら、就職・採用の選抜において学歴・資格証明書が果たす役割が、経済発展の後発国ほど急速かつ深刻な形で肥大化していく現象を「学歴病(ディプロマ・ディジーズ)」と名づけた。\n\nドーアの中心的な主張は「後発効果(late development effect)」と呼ばれる仮説であり、近代化への着手が遅い国ほど、教育が実質的な知識・技能の習得の場ではなく、資格証明書を獲得するための競争の場へと急速に変質し、その傾向がより早く、より深刻な形で表れるというものである。就職市場において資格や学歴が採用選抜の主要な基準として用いられるようになると、教育機関は実質的な学びよりも試験対策や資格取得それ自体を目的化するようになり、学歴のインフレーションが加速度的に進行する。\n\nこの議論は、ランドル・コリンズの資格社会論とも問題意識を共有しつつ、開発途上国における教育拡大政策への批判的視座を提供するものであり、日本の受験競争や学歴社会をめぐる議論、さらには近年の新興国における「高学歴ワーキングプア」問題などを考察する際にも継続的に参照されている、比較教育社会学の重要な古典である。",
