    slug: "apple-ideology-curriculum",
    title: "イデオロギーとカリキュラム(アップル)",
    reading: "いでおろぎーとかりきゅらむ",
    kana: "い",
    categories: ["sociology"],
    summary:
      "アメリカの教育学者マイケル・アップルが1979年の著書『イデオロギーとカリキュラム』で展開した理論で、学校で教えられる「公式の知識(official knowledge)」が中立的なものではなく、支配集団の文化的・経済的な覇権(ヘゲモニー)を反映し再生産していると批判的に論じた。",
    body: "マイケル・W・アップルは1979年の著書『イデオロギーとカリキュラム』(Ideology and Curriculum)において、学校教育とカリキュラムを、経済的権力と文化的権力の関係という視点から批判的に分析した。アップルはこの著作の中で、学校が伝える知識や慣行、儀礼が、あたかも価値中立的な「最善の実践」から自然に導かれたものであるという一般的な理解を強く否定し、カリキュラムの選択と編成そのものが、特定の社会集団の利害やイデオロギーを反映した政治的な過程であることを明らかにしようとした。\n\nこの議論でアップルが鍵概念として用いたのが、イギリスの文化研究者レイモンド・ウィリアムズに由来する「ヘゲモニー(覇権)」概念である。アップルによれば、学校は特定の伝統や知識だけを選択的に取り上げ、それを正統な文化として次世代に伝達する「選択的伝統」の担い手として機能し、支配的な集団の文化的・イデオロギー的な優位性を、強制ではなく人々の自発的な同意を通じて維持する「文化的・イデオロギー的覇権」の装置として働いているとされる。こうして学校で教えられる知識-アップルが「公式の知識(official knowledge)」と呼ぶもの-は、社会に存在する多様な知識のうち、支配集団にとって望ましいものが選び抜かれた結果であり、その選択過程自体が問い直されるべき対象であると論じられた。\n\nこの理論は、ブルデューの文化的再生産論や、ヤングの『Knowledge and Control』に代表される「新教育社会学」の系譜に連なりつつ、カリキュラムの内容そのものをイデオロギー分析の対象とする「批判的カリキュラム研究」を切り開いた点で大きな影響力を持った。アップルはその後も『Official Knowledge』(1993年)などの著作で議論を発展させ、教科書の内容や教育改革政策の背後にある政治的・経済的な力学を分析する批判的教育学の中心的な論者として今日も参照され続けている。",
