    body: "SSM調査は、「社会階層と社会移動全国調査（Social Stratification and Social Mobility）」の略称で、日本の階層研究を代表する大規模な社会調査です。1955年に日本社会学会が国際社会学会の国際共同研究の一環として第1回調査を実施し、以後は原則として10年ごとに行われてきました。2015年調査は7回目にあたり、少子高齢化など人口構造の変化に注目した設計となりました。さらに2025年調査も実施されています。\n\n調査では、本人の学歴、職業、所得、親の職業・学歴などをたずね、世代間の職業移動や教育達成の仕組みを分析します。教育社会学にとっては、出身階層によって学歴の到達度がどの程度異なるのか、学歴が職業的地位にどう結びつくのかを、複数の時点で比較できる貴重なデータです。地位達成モデルや教育格差、学歴社会をめぐる実証研究の多くは、SSMデータに基づいて行われてきました。\n\n東京大学の紹介記事では、1955年を基準にした相対移動率（階層間の移動のしやすさを、社会全体の職業構成の変化を取り除いて比べた指標）の変動はごく小さく、階層間の格差に大きな変化はみられないと説明されています。ただし、1955年調査は大都市・市部・郡部ごとに別々の方法で標本を抽出したため、1980〜81年にSSMトレンド分析研究会が調査票にさかのぼって全国代表標本を再構成しました。長期の比較にはこうしたデータの性質も踏まえる必要があります。",
