    body: "学歴同類婚（教育的同類婚）とは、学歴の近い男女が結婚する傾向のことです。英語では educational assortative mating と呼ばれ、大卒どうし、高卒どうしといった組み合わせが、偶然に期待されるよりも多く観察されるときに用いられます。結婚相手は学校や職場での出会いに左右されるため、学校教育は進路だけでなく、人々の出会いの場を分けることで結婚にも影響します。\n\n日本での研究では、大卒以上どうしや高卒以下どうしの結びつきが強い一方、既婚者では大卒男性と短大・専門学校卒女性の組み合わせも目立つとされます。これは、男性が女性より学歴が高い組み合わせを選びやすい傾向（上昇婚）を示しています。福田節也・余田翔平・茂木良平による国勢調査個票データの分析（1980〜2010年）など、長期の趨勢を追う研究が行われ、近年は出身大学の銘柄に着目する研究もあります。測定には対数線形モデルがよく使われますが、既婚カップルだけを分析すると結婚市場の構成の影響を見落としやすいという課題も指摘されています。\n\n教育社会学の観点から重要なのは、学歴同類婚が世帯間の格差を広げ、子どもの教育達成の差に結びつきうる点です。高学歴どうしの世帯は所得が高く、教育への投資や文化資本も豊かになりやすいため、親世代の学歴格差が子ども世代に受け継がれます。女性の高学歴化や晩婚化、未婚化が進むなかで、学歴と結婚の関係は変化しており、階層の再生産を考える重要な研究主題となっています。",
