      "1990年代末から2000年代前半に起きた、ゆとり教育下で子どもの学力が低下したかをめぐる論争。教育社会学は学力低下よりも学力の階層差の拡大を問題にした。",
    body: "学力低下論争とは、1990年代末から2000年代前半にかけて日本で広がった、子どもの学力が低下しているのかどうか、その原因は何かをめぐる議論です。きっかけの一つが、1999年6月に刊行された『分数ができない大学生』（岡部恒治・戸瀬信之・西村和雄編）です。大学生に小中学校レベルの算数・数学の問題を解かせた結果をもとに、学力低下の原因を初等・中等教育に求め、ゆとり教育路線を批判しました。当時は、教育内容を削減し完全学校週5日制を導入する学習指導要領の改訂が、2002年度の実施に向けて進められていました。\n\n教育社会学者の苅谷剛彦らは、学力の平均の低下だけでなく、家庭の階層による学習時間・学習意欲・学力の差が拡大していることを実証的に示し、問題の焦点を移しました。『階層化日本と教育危機』（2001年）や『学力と階層』（2008年）などで、「学力低下」の議論が、ゆとり教育への賛否にとどまり、階層間格差という構造的な問題を見えにくくしていると論じました。調査方法の妥当性を問う批判も出され、論争は感情的な対立となった面もあります。\n\n文部科学省は2002年に「確かな学力向上のためのアピール」を出して学力重視へ軌道修正し、2004年に公表されたPISA2003の結果（読解力の順位低下）で議論はさらに高まりました。2007年には全国学力・学習状況調査が再開され、2008年の学習指導要領改訂ではいわゆる脱ゆとりへ転換します。戦後の学力論争としては、1950年前後の基礎学力論争などに続くものと位置づけられます。",
