      "日本の中学・高校で広く行われる部活動を、自主性という建前と教員の過重労働、生徒指導機能、進学との結びつきなどから分析する教育社会学の研究領域。",
    body: "部活動は、教育課程の外で行われるスポーツや文化活動で、日本の中学校・高校では多くの生徒が参加します。学習指導要領では、生徒の自主的・自発的な参加によって行われる、学校教育の一環と位置づけられています。しかし実際には、教員が顧問として放課後や休日に指導にあたる場合が多く、教員の時間外勤務は給特法の仕組みのもとで制度上の位置づけが不明確なまま、長時間労働の要因となってきました。\n\n教育社会学者の内田良は『ブラック部活動』（東洋館出版社、2017年）などで、部活動が「自主的だから」と学校の枠組みのなかで過熱し、教員の負担や生徒の過度な練習、事故のリスクを生んでいる点を指摘しました。「自主的なのに強制され、自主的だから過熱していく」と要約される矛盾です。『部活動の社会学――学校の文化・教師の働き方』（岩波書店、2021年）のように、学校文化や教師の働き方という観点からの研究も進みました。\n\n部活動には、仲間づくりや技能の習得、居場所の提供といった教育的な意義がある一方、日本の学校が学習指導だけでなく生活指導や人間形成まで包括的に担う仕組みの一部でもあります。スポーツ推薦入試のように進学にも結びつき、保護者の期待も強いため、見直しは容易ではありません。2018年にはスポーツ庁と文化庁がそれぞれ部活動のガイドラインを策定し、現在は地域への移行が進められています。",
