    summary:
      "教員に占める女性の割合が高まった現象。小学校では教員の半数以上が女性である一方、校長など管理職では女性が少なく、教職内部のジェンダー構造が論点となる。",
    body: "教職の女性化とは、教員に占める女性の割合が長期的に高まってきた現象を指します。文部科学省の学校基本統計によれば、小学校では1969年以降、女性教員が継続して半数を超えており、2023年度には小学校と特別支援学校で教員の6割を超えています。中学校では約4割、高校では約3割が女性です。明治期の学校では男性教員が中心でしたが、女性の就業機会が限られるなかで、教職は女性が長く働き続けやすい専門職として選ばれ、女性教員の割合が高まってきました。\n\nしかし、女性教員が多いことは、教職における男女の平等を意味しません。同じ統計では、小学校の校長に占める女性の割合は2019年に初めて2割を超え、2023年には26.8%となりました。中学校・高校では、校長の女性比率は1割台にとどまります。教員の多数が女性でも管理職は男性が多いという構造は、教職内部の垂直的なジェンダー分離として分析され、昇進の機会や長時間労働と育児・介護との両立の難しさが背景にあります。都道府県による差も大きいとされます。\n\n教職を「母性的」「ケアにふさわしい」仕事とみなす見方や、男性教員が少ないことを問題視する議論もありますが、これらの主張には実証的な検討が必要です。教育社会学では、教職の女性化を、教師のライフコース、教職のキャリア形成、学校組織のジェンダー構造、子どもに伝わるジェンダー規範（隠れたカリキュラム）といった観点から研究しています。",
