    summary:
      "アーヴィング・ゴフマンが『スティグマ』（1963年）で論じた、人を社会的に信頼を損なう存在として価値づける属性や徴。教育では障害・貧困・学歴などをめぐる差別や排除の分析に用いられる。",
    body: "スティグマ（stigma）は、もとは古代ギリシャで奴隷や罪人の身体に刻んだ烙印を指す語です。カナダ生まれの社会学者アーヴィング・ゴフマンは、1963年の著作『スティグマ――傷つけられたアイデンティティについてのノート（Stigma: Notes on the Management of Spoiled Identity）』（邦訳『スティグマの社会学』）で、人が社会的に「信頼を著しく失わせる」と見なされる属性や徴を指す概念として整理しました。スティグマは属性そのものの性質ではなく、社会的な関係のなかで意味づけられる点が重要です。\n\nゴフマンは、スティグマを持つ人を二つに分けました。すでに周囲に知られている「信頼を失った者（discredited）」と、まだ知られておらず隠すことができる「信頼を失う可能性のある者（discreditable）」です。後者は、スティグマを隠すためのふるまいや情報管理に神経を使うことになります。また、スティグマには、身体的な障害や特徴、性格上の欠点や経歴、人種・民族・宗教に結びついたものなどがあるとされました。\n\n教育の場面では、障害のある子どもの特別な学級への所属、就学援助の受給、不登校や学力不振、外国につながる背景、出身校や学歴などが、スティグマ化されることがあります。この概念は、ラベリング理論やシンボリック相互作用論とも結びつき、ラベルを貼られた子どもの自己イメージや仲間関係、進路選択への影響を分析する枠組みとして用いられます。教育実践では、支援の必要性を示す際に新たなスティグマを生まないよう配慮することが課題になります。",
