    summary:
      "土井隆義が『友だち地獄』（2008年）で論じた、周囲から浮かないよう空気を読み続けることを強いられる現代の若者の友人関係と、いじめや生きづらさの背景を示す見方。",
    body: "『友だち地獄――「空気を読む」世代のサバイバル』（ちくま新書、2008年3月）は、犯罪社会学・逸脱行動論を専門とする土井隆義（筑波大学）の著作です。周囲から浮かないように気を遣い、その場の空気を読もうとする携帯電話世代の若者を取り上げ、いじめ、ひきこもり、リストカットといった現象を通して、彼らの生きづらさと希望を描きました。副題の「浮いたらオシマイ!?」が示すように、仲間から外れることへの強い不安が出発点です。\n\n土井は、現代の若者が友人との間で争点や対立を避けるために、互いの出方を細かく探り合い、場の空気に合わせて自分の振る舞いを調整していると論じます。以前のように、地域や家庭、学校の規範が共通の物差しとして人々を結びつける力が弱まると、友人関係そのものが承認の最大の源泉になります。その結果、関係を維持することへの比重が大きくなり、関係から外れる恐れが不安を高めるという、息苦しい構造が生まれます。土井はその後、個性が求められるなかで人間関係上の役割を演じる「キャラ」の問題にも議論を広げました。\n\nこの見方は、学級内の序列を示すスクールカーストや、いじめの四層構造論、SNS上のいじめを考える際にも参照されます。いじめを加害者と被害者の個人的な問題としてではなく、同調圧力が強い仲間集団のなかで起こる構造的な現象として捉える手がかりになります。一方で、「空気を読む」ことを世代全体の特徴とみなしてよいのかには慎重な検討が必要であり、実証的な研究との照合が求められます。",
