    slug: "soketsugo-nabebuta-gakko",
    title: "疎結合組織としての学校（鍋蓋型組織）",
    reading: "そけつごうそしきとしてのがっこう",
    kana: "そ",
    categories: ["sociology"],
    summary:
      "カール・ウェイクが1976年に論じた疎結合システムとしての教育組織の見方と、校長・教頭以外の教員が横並びになる日本の学校の鍋蓋型組織の特徴をあわせて理解する視点。",
    body: "疎結合（loose coupling）とは、組織の各要素が互いに緩やかにしか結びついていない状態を指します。組織心理学者のカール・E・ウェイクは、論文「疎結合システムとしての教育組織」（『アドミニストレイティブ・サイエンス・クォータリー』第21巻1号、1976年）で、教育組織は上から下までが厳密に統制された組織ではなく、要素が緩やかに結びついており、そのことが自己決定、地域への適応、環境の感知、革新を促すと論じました。教室での教師の授業は、校長や教育委員会の指示からある程度独立して行われます。この見方は、教育改革の指示が教室に届きにくい理由の説明にも使われます。\n\n日本の学校組織を説明する言葉として広く用いられるのが「鍋蓋型組織」です。校長・教頭（副校長）が上にいて、その他の教員が鍋の蓋の取っ手のように横一列に並ぶ形を表します。中央教育審議会の答申でも、校長と教頭以外の教員が横並びであることが指摘されました。フラットな構造は、学校行事など全員で課題に取り組む場面では協力を引き出しやすい反面、責任の所在があいまいになりやすく、組織的な対応が難しくなることも指摘されます。教員文化が「相互不干渉」に傾き、組織として動きにくくなる面もあるとされます。\n\n教員の多忙化やいじめ対応の複雑化を背景に、主幹教諭・指導教諭の設置や、専門スタッフと連携するチーム学校の考え方が導入され、ピラミッド型に近い管理運営への転換が進められてきました。ただし鍋蓋型の文化は残っており、疎結合の利点（現場の自律性）を保ちながら、組織としての対応力を高める方法が課題となっています。",
