    body: "フランスの社会学者ピエール・ブルデューが提唱した概念であり、文化資本の基本形態の一つである。個人の身体に長期的な訓練や家庭環境を通じて刻み込まれた言語遣い、発音、身のこなし、美的感覚などの性向システム（ハビトゥス）を指す。\n\n学校教育は一見すると能力主義的で中立に見えるが、実際には出身階層の上層が持つ洗練された身体化された文化資本を正当な学力や品性として評価する。家庭で自然に培われた文化的所作を持たない下層階層出身の児童生徒は、初期段階から学習上の不利を被り、階層格差が教育を通じて再生産される。\n\n現代の教育改革や公正な機会保障においては、学校が暗黙の前提としている文化的規範を可視化し、公教育の場で基礎的な言語運用や文化的経験を補償的に提供する政策が求められている。家庭環境の格差が子どもの尊厳や進路選択を制約しない仕組みづくりが不可欠である。",
