    body: "イギリスの社会学者バジル・バーンスティンが言語社会化理論の中で提唱した概念である。共有された経験や身近な人間関係を前提とし、言葉そのものによる詳細な説明を省略して身振りや共感に依存する会話様式を指す。主として労働者階級の家庭環境で形成されやすい。\n\n学校教育では論理的で普遍的な言語運用が求められるため、制限コードを主として用いる子どもは、教員の指示や抽象的な教科書記述を十分に読み解けない困難に直面する。この言語様式の違いが認知能力自体の劣位と誤認され、選別を通じて階層的格差が定着する。\n\n現代の教育現場では、制限コードを否定的に扱うのではなく、児童生徒が親しんできた表現を受け止めつつ、公的な場での抽象的・論理的表現を無理なく身につけられる丁寧な指導が求められている。すべての子どもの学習権を保障する言語教育の再構築が必要である。",
