    body: "バジル・バーンスティンが知識社会学の枠組みから提示したカリキュラム構造論の基本概念である。教育課程において各教科や学問領域の境界がどれほど厳格に保たれているかの度合いを指し、強い分類は各教科の孤立を、弱い分類は教科横断的な統合を意味する。\n\n強い分類のもとでは、正統な学術的知識と日常的経験が厳格に切り離され、知識を独占する専門家や教員の権力が保持される。一方、弱い分類では境界が緩和されて日常知と学校知が結びつきやすくなるが、評価基準が見えにくくなり、かえって家庭の文化資本に恵まれた層が有利になる逆説も生じる。\n\n現代のカリキュラム改革における学際的探究や総合的な学習の導入は、分類の緩和を目指す動きとして位置づけられる。公正な教育機会を保障するためには、教科の専門性を保ちながらも、学習者が孤立せず主体的に知識を関連づけられる明確な枠組み設計が不可欠である。",
