    body: "イギリスの社会学者ポール・ウィリスが主著『ハマータウンの野郎ども』で明らかにした概念である。学校の従順さや知育中心主義に対して、労働者階級の少年グループ（ラッズ）が反発し、独自の価値観や男らしさを誇示する抵抗の文化様式を指す。\n\nラッズは学校の形式的な平等主義や権威を見抜き、机上の勉強を拒絶して肉体労働の男らしさを称揚する。しかし、この主体的な対抗行動こそが、彼ら自身を肉体労働者の地位へと進路選択させ、結果として既存の階級構造を自発的に再生産してしまう逆説を生み出す。\n\n現代の高校教育や生徒指導においても、学校文化に適応できない生徒が抱く違和感や対抗意識を単なる逸脱として排除しない配慮が求められる。生徒の多様な価値観を肯定しつつ、公正で尊厳あるキャリア形成を支える包摂的な学校組織の構築が不可欠である。",
