    body: "日本の教育社会学における大規模な実証調査をもとに提示された概念である。学びへの動機づけや学習意欲が単なる個人の内面や努力の問題ではなく、家庭の社会経済的階層によって不均等に配分されている「意欲の格差」の構造的現実を指摘した。\n\n学習指導要領の改訂や自律的学習の推進期において、勉強する意義を見出せる層と見出せない層の分断が進んだ。社会階層の高い家庭の子どもは将来の報酬を見通して意欲を維持する一方、不利な環境にある子どもは学習意欲を喪失し、意欲の差が学力格差を増幅させる循環が生じる。\n\n現代の教育施策では、意欲を自己責任化せず、すべての学習者に学習の動機づけを育む公的な支援体制が求められる。わかりやすい授業展開や基礎学力の確実な定着、個別学習支援を通じて、学ぶ喜びと学習意欲を公教育が手厚く保障することが肝要である。",
