    body: "学歴同類婚とは、同等水準の学歴を持つ者同士が結婚する傾向を指す社会学の重要概念である。高等教育の拡大と女性の大学進学率の上昇に伴い、男女双方が高い学歴を持つ世帯が増加し、近代社会における家族形成と階層構造の変容を分析する焦点となってきた。\n\n高学歴層同士の結合は共働きを通じて世帯所得を急増させる一方、低学歴層同士の世帯では経済的困窮が生じやすく、世帯間格差が二極化する。高所得・高学歴世帯による子どもの教育への集中投資は、次世代の学力や進学実績の格差を拡大し、階層の固定化を強力に促進する。\n\n世帯の経済力に左右されない教育機会の公正を確保するため、公教育の役割を抜本的に再強化することが求められている。高等教育の無償化や給付型奨学金の拡充を進め、生まれ育った家庭環境によって子どもの将来が決定されない制度設計が必要である。",
