    body: "ヤングケアラーとは、本来大人が担うべき家事や家族の介護、情緒的な世話を日常的に過度に行っている子どもを指す概念である。近年の社会調査によってその存在が可視化され、子どもの健やかな成長と教育を受ける権利を脅かす深刻な社会問題として認識された。\n\n重い介護負担は、遅刻や早退、宿題の未提出など学習時間の極端な制約をもたらし、学力低下や不登校、進路の断念へと直結する。また家庭内の問題として潜在化しやすく、学校現場で発見が遅れることで、社会的孤立と学歴取得機会の喪失を深刻化させる。\n\n学校が福祉や医療機関と連携し、支援を家庭全体で受け止める早期発見と包括的支援の体制整備が急務である。スクールソーシャルワーカーの活用や教員の理解促進を進め、子どもが子どもらしく学び、自己の進路を自律的に選択できる環境を保障しなければならない。",
