    body: "1980年代後半以降に急増したニューカマーと呼ばれる外国人家庭の生徒は、義務教育終了後の高校進学において深刻な制度的および実質的障壁に直面してきた。学歴社会である日本において、高校進学の可否は将来の社会的移動や職業獲得を決定づける分岐点となる。\n\n高校入試における言語の壁や保護者の制度理解の不足により、進学断念や中途退学のリスクが高く、進学できても進路の多様性が狭められやすい。結果として不安定な低賃金労働に従事せざるを得ず、外国人コミュニティの世代間格差が再生産される要因となっている。\n\n高校教育の実質的な機会均等を保障するため、入試での特別措置や多言語による進路相談、高校における日本語指導体制の確立が不可欠である。公教育を通じた公正な社会的移動の経路を開くことが、多文化社会の安定と公正の確立に強く求められている。",
