    body: "知識やテスト得点以外の自制心、やり抜く力、協調性などの非認知能力が、将来の成功を左右する要因として脚光を浴びている。教育社会学では、非認知能力の強調が個人の努力や家庭の成育環境の差異を覆い隠し、新たな格差の正当化装置になり得ると警戒される。\n\n非認知能力の育成には、幼少期からの安心できる養育環境や豊かな対話、多様な文化的体験の蓄積が深く関わっている。経済的・時間的余裕のある家庭ほどそうした環境を整えやすく、貧困家庭の子どもが能力不足という不当な評価を受ける新たな階層再生産の機制が働く。\n\n個人の資質に格差の全責任を帰する自己責任論を排し、すべての子どもが自己肯定感を育める学校教育の支援が求められる。非認知的な発達を支える心理的・福祉的アプローチを公教育全体で保障し、構造的不平等を固定化させない包摂的な実践が重要である。",
