    body: "個人の努力や才能によって地位が配分されるべきだとするメリトクラシーは、近代教育制度の正当性を支える中核原理であった。しかし個人の能力形成自体が家庭環境や運に強く制約されている事実が明らかになり、能力主義を根本から見直す議論が台頭した。\n\n能力主義は成功者に過度な優越感をもたらし、敗者には自己責任という不当な評価を下すことで社会的な分断や格差の正当化を深めてきた。知識基盤社会において求められる能力が多次元化するにつれ、特定の一元的指標による序列化は多くの学習者を排除し尊厳を傷つける構造を露呈している。\n\n業績による選別を超え、すべての人間が無条件に尊厳を持つという共通善の思想に基づく教育の再構築が求められる。他者との共生や互恵的な関係性を重んじる新たな能力観を培い、過度な競争から共生へと大きく転換する教育改革が公正な社会の礎となる。",
