    body: "国境を越えて移動する家族や高度専門人材の増加に伴い、国際基準の教育課程を提供する国際学校への進学が世界的に拡大している。教育社会学では、国境に縛られないトランスナショナルな教育移動が、地球規模の特権階級による文化資本獲得戦略として分析される。\n\n高額な学費を支払える富裕層は、国際的な進学資格や英語での高度な教育を早期から獲得し、国内の学歴競争からいち早く脱出する。この動きは国民国家の公教育制度を空洞化させ、自国の共通基盤から遊離した新たな超国家的エリート層を再生産する格差構造を生み出す。\n\n国際的な教育流動性の進展を踏まえつつ、公教育の魅力を高め民主的な市民性を培う普遍的教育の再構築が急務である。特定の階層のみが恩恵を受ける分断を防ぎ、すべての児童生徒にグローバルな視野と協働の機会を公的に保障する政策展開が求められる。",
